AssistantMessageToolRequest(name='create', tool_call_id='tooluse_5W5LMdvccSQwBVoRj0VAr5', arguments={'file_text': '// Cart state
let cart = {
    items: 0,
    products: []
};

// Initialize cart from localStorage
function initializeCart() {
    const savedCart = localStorage.getItem('luxeCart');
    if (savedCart) {
        try {
            cart = JSON.parse(savedCart);
            updateCartButton();
        } catch (e) {
            console.error('Failed to load cart:', e);
        }
    }
}

// Update cart button with item count
function updateCartButton() {
    const cartBtn = document.getElementById('cart-btn');
    if (cartBtn) {
        cartBtn.setAttribute('aria-label', `Shopping cart, ${cart.items} items`);
    }
}

// Save cart to localStorage
function saveCart() {
    localStorage.setItem('luxeCart', JSON.stringify(cart));
}

// Add to cart handler
function addToCart(event) {
    const button = event.target.closest('.btn-add-cart');
    if (!button) return;

    const card = button.closest('.product-card');
    const productName = card.querySelector('h3').textContent;
    const productPrice = card.querySelector('.price').textContent;

    // Update cart state
    cart.items++;
    cart.products.push({
        name: productName,
        price: productPrice,
        timestamp: new Date().toISOString()
    });

    saveCart();
    updateCartButton();

    // Visual feedback
    const originalText = button.textContent;
    button.textContent = 'Added!';
    button.style.backgroundColor = 'var(--color-success)';

    setTimeout(() => {
        button.textContent = originalText;
        button.style.backgroundColor = '';
    }, 2000);
}

// Newsletter signup handler
function handleNewsletterSignup(event) {
    event.preventDefault();

    const emailInput = document.getElementById('email-input');
    const messageDiv = document.getElementById('newsletter-message');
    const email = emailInput.value.trim();

    // Validate email
    if (!email || !isValidEmail(email)) {
        messageDiv.textContent = 'Please enter a valid email address.';
        messageDiv.className = 'newsletter-message error';
        return;
    }

    // Simulate subscription
    messageDiv.textContent = 'Subscribing...';
    messageDiv.className = 'newsletter-message';

    setTimeout(() => {
        messageDiv.textContent = `Welcome! Check your email at ${email} for exclusive offers.`;
        messageDiv.className = 'newsletter-message success';
        emailInput.value = '';

        // Clear success message after 5 seconds
        setTimeout(() => {
            messageDiv.textContent = '';
            messageDiv.className = 'newsletter-message';
        }, 5000);
    }, 800);
}

// Email validation
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

// Search button handler
function handleSearch() {
    const searchBtn = document.getElementById('search-btn');
    if (searchBtn) {
        searchBtn.addEventListener('click', () => {
            alert('Search functionality would be implemented here.');
        });
    }
}

// Smooth scroll for navigation links
function initSmoothScroll() {
    document.querySelectorAll('a[href^="#"]').forEach(link => {
        link.addEventListener('click', function(event) {
            const href = this.getAttribute('href');
            if (href === '#' || href === '') return;

            const target = document.querySelector(href);
            if (target) {
                event.preventDefault();
                target.scrollIntoView({ behavior: 'smooth' });
            }
        });
    });
}

// Keyboard navigation for buttons
function initKeyboardNavigation() {
    document.querySelectorAll('.btn, .icon-btn, .btn-add-cart').forEach(button => {
        button.addEventListener('keydown', (event) => {
            if (event.key === ' ' || event.key === 'Enter') {
                event.preventDefault();
                button.click();
            }
        });
    });
}

// Add to cart event delegation
document.addEventListener('DOMContentLoaded', () => {
    // Initialize
    initializeCart();
    handleSearch();
    initSmoothScroll();
    initKeyboardNavigation();

    // Add to cart delegation
    document.addEventListener('click', (event) => {
        if (event.target.closest('.btn-add-cart')) {
            addToCart(event);
        }
    });

    // Newsletter form
    const form = document.querySelector('.newsletter-form');
    if (form) {
        form.addEventListener('submit', handleNewsletterSignup);
    }

    // Keyboard focus management
    document.addEventListener('keydown', (event) => {
        // Press Escape to clear newsletter message
        if (event.key === 'Escape') {
            const messageDiv = document.getElementById('newsletter-message');
            if (messageDiv) {
                messageDiv.textContent = '';
                messageDiv.className = 'newsletter-message';
            }
        }
    });
});

// Handle cart button clicks
document.addEventListener('DOMContentLoaded', () => {
    const cartBtn = document.getElementById('cart-btn');
    if (cartBtn) {
        cartBtn.addEventListener('click', () => {
            if (cart.items === 0) {
                alert('Your cart is empty.');
            } else {
                alert(`You have ${cart.items} item(s) in your cart.`);
            }
        });
    }
});

// Announce dynamic updates to screen readers
function announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.className = 'sr-only';
    announcement.textContent = message;
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 1000);
