/* Root & Global Styles */
:root {
    --color-dark: #0a0e27;
    --color-darker: #050810;
    --color-accent: #d4af37;
    --color-accent-dark: #a68c2e;
    --color-text-primary: #f5f5f5;
    --color-text-secondary: #b8b8b8;
    --color-border: #2a2e4a;
    --color-hover: #1a1f3a;
    --color-success: #4ade80;
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;
    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.3);
    --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.5);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

@media (prefers-reduced-motion: reduce) {
    :root {
        --transition: none;
    }
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--color-dark);
    color: var(--color-text-primary);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    font-size: 16px;
    line-height: 1.6;
}

/* Skip Link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--color-accent);
    color: var(--color-dark);
    padding: var(--spacing-sm);
    text-decoration: none;
    z-index: 100;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
}

/* Screen reader only */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-weight: 600;
    line-height: 1.3;
    margin-bottom: var(--spacing-md);
}

h1 {
    font-size: 2.5rem;
}

h2 {
    font-size: 2rem;
}

h3 {
    font-size: 1.25rem;
}

p {
    margin-bottom: var(--spacing-md);
    color: var(--color-text-secondary);
}

a {
    color: var(--color-accent);
    text-decoration: none;
    transition: var(--transition);
}

a:hover,
a:focus {
    color: #e6c547;
}

a:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Header */
.header {
    background-color: var(--color-darker);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.header-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-lg);
    padding: var(--spacing-md) 0;
}

.logo h1 {
    font-size: 1.75rem;
    margin: 0;
    letter-spacing: 2px;
}

.nav-main {
    flex: 1;
}

.nav-main ul {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-main a {
    color: var(--color-text-primary);
    font-size: 0.95rem;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
}

.nav-main a:hover,
.nav-main a:focus {
    color: var(--color-accent);
    background-color: var(--color-hover);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

.icon-btn {
    background: none;
    border: none;
    color: var(--color-text-primary);
    font-size: 1.5rem;
    cursor: pointer;
    padding: var(--spacing-xs);
    border-radius: 4px;
    transition: var(--transition);
}

.icon-btn:hover,
.icon-btn:focus {
    color: var(--color-accent);
    background-color: var(--color-hover);
}

.icon-btn:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Hero Section */
.hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: var(--spacing-2xl);
    max-width: 1400px;
    margin: 0 auto;
    padding: var(--spacing-2xl) var(--spacing-md);
    background: linear-gradient(135deg, #1a1f3a 0%, #0f1229 100%);
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: var(--spacing-lg);
}

.hero-content p {
    font-size: 1.1rem;
    margin-bottom: var(--spacing-xl);
}

.hero-image {
    height: 400px;
    background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-dark) 100%);
    border-radius: 8px;
    box-shadow: var(--shadow-lg);
}

/* Main Container */
.section-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

main > section {
    padding: var(--spacing-2xl) 0;
}

main > section:nth-child(odd) {
    background-color: var(--color-dark);
}

main > section:nth-child(even) {
    background-color: #0f1229;
}

/* Featured Products */
.featured-products {
    background-color: var(--color-dark);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.product-card {
    background-color: var(--color-hover);
    border: 1px solid var(--color-border);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover,
.product-card:focus-within {
    border-color: var(--color-accent);
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.product-image {
    height: 250px;
    background: linear-gradient(135deg, #2a2e4a 0%, #1a1f3a 100%);
}

.product-info {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    margin-bottom: var(--spacing-sm);
    font-size: 1.1rem;
}

.product-category {
    font-size: 0.85rem;
    color: var(--color-accent);
    margin-bottom: var(--spacing-sm);
}

.product-description {
    flex: 1;
    margin-bottom: var(--spacing-md);
    font-size: 0.95rem;
}

.product-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-md);
}

.price {
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--color-accent);
}

/* Deals Section */
.deals-section {
    background-color: #0f1229;
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.deal-card {
    background: linear-gradient(135deg, var(--color-hover) 0%, #0f1229 100%);
    border: 1px solid var(--color-border);
    border-radius: 8px;
    padding: var(--spacing-lg);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 200px;
}

.deal-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.deal-card-large {
    grid-column: span 1;
    grid-row: span 2;
    position: relative;
    overflow: hidden;
}

.deal-image {
    position: absolute;
    right: 0;
    top: 0;
    width: 50%;
    height: 100%;
    background: linear-gradient(135deg, var(--color-accent) 0%, var(--color-accent-dark) 100%);
    border-radius: 0 8px 8px 0;
}

.deal-card-large .deal-content {
    position: relative;
    z-index: 2;
}

.deal-badge {
    display: inline-block;
    background-color: var(--color-accent);
    color: var(--color-dark);
    padding: var(--spacing-xs) var(--spacing-sm);
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-bottom: var(--spacing-md);
}

.deal-card h3 {
    margin-bottom: var(--spacing-sm);
}

.deal-card p {
    margin-bottom: var(--spacing-md);
}

/* Editorial Section */
.editorial-section {
    background-color: var(--color-dark);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
    margin-top: var(--spacing-xl);
}

.editorial-card {
    background-color: var(--color-hover);
    border: 1px solid var(--color-border);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--color-accent);
    transform: translateY(-4px);
    box-shadow: var(--shadow-md);
}

.editorial-image {
    height: 200px;
    background: linear-gradient(135deg, #2a2e4a 0%, #1a1f3a 100%);
}

.editorial-content {
    padding: var(--spacing-lg);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-content time {
    font-size: 0.85rem;
    color: var(--color-accent);
    margin-bottom: var(--spacing-sm);
}

.editorial-content h3 {
    margin-bottom: var(--spacing-md);
}

.editorial-content h3 a {
    color: var(--color-text-primary);
}

.editorial-content h3 a:hover,
.editorial-content h3 a:focus {
    color: var(--color-accent);
}

.editorial-content p {
    flex: 1;
    margin-bottom: var(--spacing-md);
}

.read-more {
    display: inline-block;
    font-weight: 500;
    padding-bottom: 4px;
    border-bottom: 2px solid transparent;
    transition: var(--transition);
}

.read-more:hover,
.read-more:focus {
    border-bottom-color: var(--color-accent);
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, #1a1f3a 0%, #0f1229 100%);
    padding: var(--spacing-2xl) 0;
}

.newsletter-container {
    text-align: center;
}

.newsletter-container h2 {
    margin-bottom: var(--spacing-md);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-md);
    max-width: 500px;
    margin: var(--spacing-xl) auto;
    flex-wrap: wrap;
    justify-content: center;
}

.form-group {
    flex: 1;
    min-width: 250px;
}

.form-group input {
    width: 100%;
    padding: var(--spacing-sm);
    background-color: var(--color-hover);
    border: 1px solid var(--color-border);
    border-radius: 4px;
    color: var(--color-text-primary);
    font-size: 1rem;
    transition: var(--transition);
}

.form-group input:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
    border-color: var(--color-accent);
}

.form-group input::placeholder {
    color: var(--color-text-secondary);
}

.newsletter-message {
    margin-top: var(--spacing-md);
    min-height: 1.5rem;
    font-size: 0.95rem;
}

.newsletter-message.success {
    color: var(--color-success);
}

.newsletter-message.error {
    color: #ef4444;
}

/* Buttons */
.btn {
    padding: var(--spacing-sm) var(--spacing-lg);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-dark);
}

.btn-primary:hover,
.btn-primary:focus {
    background-color: #e6c547;
}

.btn-secondary {
    background-color: transparent;
    color: var(--color-accent);
    border: 2px solid var(--color-accent);
}

.btn-secondary:hover,
.btn-secondary:focus {
    background-color: var(--color-accent);
    color: var(--color-dark);
}

.btn-small {
    padding: var(--spacing-xs) var(--spacing-md);
    font-size: 0.9rem;
    letter-spacing: 0.5px;
}

.btn-add-cart {
    background-color: var(--color-accent);
    color: var(--color-dark);
    border: 2px solid var(--color-accent);
}

.btn-add-cart:hover,
.btn-add-cart:focus {
    background-color: transparent;
    color: var(--color-accent);
}

.btn:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Footer */
.footer {
    background-color: var(--color-darker);
    border-top: 1px solid var(--color-border);
    padding: var(--spacing-2xl) 0 var(--spacing-lg);
    margin-top: var(--spacing-2xl);
}

.footer-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
}

.footer-section h3 {
    margin-bottom: var(--spacing-md);
    font-size: 1rem;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: var(--color-text-secondary);
}

.footer-section a:hover,
.footer-section a:focus {
    color: var(--color-accent);
}

.footer-bottom {
    text-align: center;
    padding-top: var(--spacing-lg);
    border-top: 1px solid var(--color-border);
    color: var(--color-text-secondary);
}

/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }

    .header-top {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .nav-main {
        order: 3;
        flex-basis: 100%;
    }

    .nav-main ul {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .hero {
        grid-template-columns: 1fr;
        gap: var(--spacing-lg);
        padding: var(--spacing-lg) var(--spacing-md);
    }

    .hero-content h2 {
        font-size: 2rem;
    }

    .hero-image {
        height: 300px;
    }

    .deals-grid .deal-card-large {
        grid-column: span 1;
        grid-row: span 1;
    }

    .deal-image {
        display: none;
    }

    main > section {
        padding: var(--spacing-lg) 0;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .form-group {
        min-width: auto;
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-md: 1rem;
        --spacing-lg: 1.5rem;
        --spacing-xl: 2rem;
        --spacing-2xl: 2.5rem;
    }

    body {
        font-size: 14px;
    }

    h1 {
        font-size: 1.5rem;
    }

    h2 {
        font-size: 1.25rem;
    }

    .logo h1 {
        font-size: 1.25rem;
    }

    .nav-main ul {
        gap: var(--spacing-sm);
    }

    .nav-main a {
        padding: var(--spacing-xs) var(--spacing-xs);
        font-size: 0.85rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .product-card,
    .deal-card,
    .editorial-card {
        min-height: auto;
    }

    .footer-container {
        grid-template-columns: 1fr;
    }
}

/* High Contrast Mode Support */
@media (prefers-contrast: more) {
    a:focus {
        outline-width: 3px;
    }

    .btn:focus {
        outline-width: 3px;
    }

    .icon-btn:focus {
        outline-width: 3px;
    }
}

/* Forced Colors Mode Support */
@media (forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card {
        border: 2px solid CanvasText;
    }

    .hero-image,
    .product-image,
    .editorial-image,
    .deal-image {
        background: ButtonBorder;
    }

    .btn-primary,
    .btn-add-cart {
        background-color: ButtonFace;
        color: ButtonText;
    }

    a {
        text-decoration: underline;
    }
}

// Cart state
let cart = {
    items: 0,
    products: []
};

// Initialize cart from localStorage
function initializeCart() {
    const savedCart = localStorage.getItem('luxeCart');
    if (savedCart) {
        try {
            cart = JSON.parse(savedCart);
            updateCartButton();
        } catch (e) {
            console.error('Failed to load cart:', e);
        }
    }
}

// Update cart button with item count
function updateCartButton() {
    const cartBtn = document.getElementById('cart-btn');
    if (cartBtn) {
        cartBtn.setAttribute('aria-label', `Shopping cart, ${cart.items} items`);
    }
}

// Save cart to localStorage
function saveCart() {
    localStorage.setItem('luxeCart', JSON.stringify(cart));
}

// Add to cart handler
function addToCart(event) {
    const button = event.target.closest('.btn-add-cart');
    if (!button) return;

    const card = button.closest('.product-card');
    const productName = card.querySelector('h3').textContent;
    const productPrice = card.querySelector('.price').textContent;

    // Update cart state
    cart.items++;
    cart.products.push({
        name: productName,
        price: productPrice,
        timestamp: new Date().toISOString()
    });

    saveCart();
    updateCartButton();

    // Visual feedback
    const originalText = button.textContent;
    button.textContent = 'Added!';
    button.style.backgroundColor = 'var(--color-success)';

    setTimeout(() => {
        button.textContent = originalText;
        button.style.backgroundColor = '';
    }, 2000);
}

// Newsletter signup handler
function handleNewsletterSignup(event) {
    event.preventDefault();

    const emailInput = document.getElementById('email-input');
    const messageDiv = document.getElementById('newsletter-message');
    const email = emailInput.value.trim();

    // Validate email
    if (!email || !isValidEmail(email)) {
        messageDiv.textContent = 'Please enter a valid email address.';
        messageDiv.className = 'newsletter-message error';
        return;
    }

    // Simulate subscription
    messageDiv.textContent = 'Subscribing...';
    messageDiv.className = 'newsletter-message';

    setTimeout(() => {
        messageDiv.textContent = `Welcome! Check your email at ${email} for exclusive offers.`;
        messageDiv.className = 'newsletter-message success';
        emailInput.value = '';

        // Clear success message after 5 seconds
        setTimeout(() => {
            messageDiv.textContent = '';
            messageDiv.className = 'newsletter-message';
        }, 5000);
    }, 800);
}

// Email validation
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

// Search button handler
function handleSearch() {
    const searchBtn = document.getElementById('search-btn');
    if (searchBtn) {
        searchBtn.addEventListener('click', () => {
            alert('Search functionality would be implemented here.');
        });
    }
}

// Smooth scroll for navigation links
function initSmoothScroll() {
    document.querySelectorAll('a[href^="#"]').forEach(link => {
        link.addEventListener('click', function(event) {
            const href = this.getAttribute('href');
            if (href === '#' || href === '') return;

            const target = document.querySelector(href);
            if (target) {
                event.preventDefault();
                target.scrollIntoView({ behavior: 'smooth' });
            }
        });
    });
}

// Keyboard navigation for buttons
function initKeyboardNavigation() {
    document.querySelectorAll('.btn, .icon-btn, .btn-add-cart').forEach(button => {
        button.addEventListener('keydown', (event) => {
            if (event.key === ' ' || event.key === 'Enter') {
                event.preventDefault();
                button.click();
            }
        });
    });
}

// Add to cart event delegation
document.addEventListener('DOMContentLoaded', () => {
    // Initialize
    initializeCart();
    handleSearch();
    initSmoothScroll();
    initKeyboardNavigation();

    // Add to cart delegation
    document.addEventListener('click', (event) => {
        if (event.target.closest('.btn-add-cart')) {
            addToCart(event);
        }
    });

    // Newsletter form
    const form = document.querySelector('.newsletter-form');
    if (form) {
        form.addEventListener('submit', handleNewsletterSignup);
    }

    // Keyboard focus management
    document.addEventListener('keydown', (event) => {
        // Press Escape to clear newsletter message
        if (event.key === 'Escape') {
            const messageDiv = document.getElementById('newsletter-message');
            if (messageDiv) {
                messageDiv.textContent = '';
                messageDiv.className = 'newsletter-message';
            }
        }
    });
});

// Handle cart button clicks
document.addEventListener('DOMContentLoaded', () => {
    const cartBtn = document.getElementById('cart-btn');
    if (cartBtn) {
        cartBtn.addEventListener('click', () => {
            if (cart.items === 0) {
                alert('Your cart is empty.');
            } else {
                alert(`You have ${cart.items} item(s) in your cart.`);
            }
        });
    }
});

// Announce dynamic updates to screen readers
function announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.className = 'sr-only';
    announcement.textContent = message;
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 1000);
}

